    # Q136: Metals, Non-Metals, Periodic Table & Acids (48 distinct properties)
    prop_pool = [
        ("Which metal is liquid at room temperature (25°C)?", "कमरे के सामान्य तापमान (25°C) पर कौन सी धातु द्रव अवस्था में पाई जाती है?", "Mercury (Hg)", "पारा / मरकरी (Hg)", ["Bromine", "Gallium", "Lead"], ["ब्रोमीन", "गैलियम", "सीसा"], "Mercury is the only liquid metal at standard room temperature.", "पारा एकमात्र धातु है जो सामान्य तापमान पर द्रव अवस्था में रहती है।"),
        ("Which non-metal is in liquid state at standard room temperature?", "कमरे के सामान्य तापमान पर कौन सी अधातु द्रव अवस्था में होती है?", "Bromine (Br2)", "ब्रोमीन (Br2)", ["Chlorine", "Iodine", "Phosphorus"], ["क्लोरीन", "आयोडीन", "फॉस्फोरस"], "Bromine is a dark reddish-brown fuming liquid non-metal.", "ब्रोमीन एकमात्र अधातु है जो सामान्य ताप पर द्रव रूप में पाई जाती है।"),
        ("Which low-melting metals can melt simply by the warmth of human palm?", "कौन सी धातुएं हथेली पर रखने मात्र से ही पिघल जाती हैं?", "Gallium (Ga) and Cesium (Cs)", "गैलियम (Ga) एवं सीजियम (Cs)", ["Sodium and Potassium", "Aluminium and Zinc", "Lead and Tin"], ["सोडियम एवं पोटैशियम", "एल्युमिनियम एवं जिंक", "लेड एवं टिन"], "Melting point of Gallium is 29.76°C, lower than human body temperature (37°C).", "गैलियम का गलनांक 29.76°C होता है जो मानव शरीर के ताप (37°C) से कम है।"),
        ("Which metal is the best conductor of electricity and heat?", "विद्युत एवं ऊष्मा का सर्वोत्तम सुचालक कौन सी धातु है?", "Silver (Ag)", "चांदी / सिल्वर (Ag)", ["Copper", "Gold", "Aluminium"], ["तांबा", "सोना", "एल्युमिनियम"], "Silver has highest electrical conductivity, followed closely by copper and gold.", "विद्युत चालकता में चांदी प्रथम स्थान पर तथा तांबा दूसरे स्थान पर आता है।"),
        ("Which elements are the most malleable and ductile of all known metals?", "सर्वाधिक आघातवर्ध्य (Malleable) एवं तन्य (Ductile) धातु कौन सी है?", "Gold (Au) and Platinum (Pt)", "सोना (Au) एवं प्लेटिनम (Pt)", ["Silver", "Copper", "Aluminium"], ["चांदी", "तांबा", "एल्युमिनियम"], "One gram of gold can be drawn into a thin wire over 2 kilometers long.", "सोने की आघातवर्धनीयता सर्वाधिक होती है; 1 ग्राम से 2 किमी लंबा तार खिंच सकता है।"),
        ("Which is the hardest naturally occurring allotrope known on Earth?", "पृथ्वी पर पाया जाने वाला प्राकृतिक रूप से सबसे कठोरतम पदार्थ कौन सा है?", "Diamond (allotrope of Carbon)", "हीरा (कार्बन का अपररूप)", ["Corundum", "Quartz", "Topaz"], ["कोरन्डम", "क्वार्ट्ज", "टोपाज"], "Giant covalent tetrahedral lattice gives diamond maximum rating (10) on Mohs hardness scale.", "हीरे में कार्बन परमाणुओं का त्रिविमीय चतुष्फलकीय जाल इसे सबसे कठोर बनाता है।"),
        ("Which carbon allotrope is a good conductor of electricity due to free pi electrons?", "मुक्त इलेक्ट्रॉनों के कारण कार्बन का कौन सा अपररूप विद्युत का अच्छा चालक है?", "Graphite", "ग्रेफाइट (Graphite)", ["Diamond", "Fullerene", "Coal"], ["हीरा", "फुलरीन", "कोयला"], "Hexagonal layered lattice contains delocalized electrons that conduct electricity.", "ग्रेफाइट की षट्कोणीय परतों में मुक्त इलेक्ट्रॉन विद्युत का संचलन करते हैं।"),
        ("Brass is a non-ferrous alloy consisting of", "पीतल (Brass) किन धातुओं की मिश्रधातु है?", "Copper (~70%) and Zinc (~30%)", "तांबा (~70%) एवं जस्ता (~30%)", ["Copper and Tin", "Copper and Nickel", "Zinc and Tin"], ["तांबा एवं टिन", "तांबा एवं निकल", "जस्ता एवं टिन"], "Brass is an alloy of Copper (Cu) and Zinc (Zn).", "पीतल तांबे (Cu) और जस्ते (Zn) की मिश्रधातु है।"),
        ("Bronze is an ancient alloy primarily composed of", "कांसा (Bronze) मुख्यतः किन धातुओं की मिश्रधातु है?", "Copper (~88-90%) and Tin (~10-12%)", "तांबा (~90%) एवं टिन (~10%)", ["Copper and Zinc", "Copper and Lead", "Tin and Lead"], ["तांबा एवं जस्ता", "तांबा एवं सीसा", "टिन एवं सीसा"], "Bronze gave name to the Bronze Age civilization.", "कांसा तांबे (Cu) और टिन (Sn) की मिश्रधातु है।"),
        ("German Silver alloy contains what percentage of actual silver?", "जर्मन सिल्वर (German Silver) में कितने प्रतिशत वास्तविक चांदी होती है?", "0% (Contains Copper, Zinc, and Nickel)", "0% (इसमें तांबा, जस्ता एवं निकल होता है)", ["50%", "25%", "80%"], ["50%", "25%", "80%"], "Named for silver-like appearance; composed of Cu (60%), Zn (20%), Ni (20%).", "जर्मन सिल्वर में चांदी बिल्कुल नहीं (0%) होती; यह Cu, Zn और Ni की मिश्रधातु है।"),
        ("Stainless Steel owes its rust-resistant stainless property to the addition of", "स्टेनलेस स्टील को जंग-रोधी बनाने हेतु लोहे में मुख्यतः क्या मिलाया जाता है?", "Chromium (Cr, ~10.5-18%) and Nickel (Ni)", "क्रोमियम (~18%) एवं निकल (~8%)", ["Zinc", "Lead", "Tin"], ["जस्ता", "सीसा", "टिन"], "Chromium forms an invisible self-healing passivation oxide film on the steel surface.", "क्रोमियम सतह पर ऑक्साइड की रक्षात्मक परत बनाकर लोहे को जंग से बचाता है।"),
        ("Solder wire used for joining electrical circuits is an alloy of", "इलेक्ट्रॉनिक परिपथों में टांका लगाने वाला सोल्डर (Solder) किसका मिश्रण है?", "Lead (Pb, ~37%) and Tin (Sn, ~63%)", "सीसा (Pb) एवं टिन (Sn)", ["Copper and Tin", "Zinc and Copper", "Aluminium and Lead"], ["तांबा एवं टिन", "जस्ता एवं तांबा", "एल्युमिनियम एवं लेड"], "Eutectic lead-tin alloy melts at low temperature (183°C) for clean electrical joints.", "सोल्डर सीसे (Lead) और टिन (Tin) की निम्न गलनांक वाली मिश्रधातु है।"),
        ("An amalgam is defined in chemistry as any alloy containing", "रसायन विज्ञान में अमलगम (Amalgam) किस धातु के मिश्रधातु को कहा जाता है?", "Mercury (Hg)", "पारा / मरकरी (Hg)", ["Lead", "Silver", "Gold"], ["सीसा", "चांदी", "सोना"], "Dental amalgams use mercury alloyed with silver, tin, and copper.", "पारे (Mercury) के साथ किसी अन्य धातु की मिश्रधातु को अमलगम कहते हैं।"),
        ("Which metal does NOT form an amalgam with mercury and can store it safely?", "कौन सी धातु पारे के साथ अमलगम नहीं बनाती और इसे रखने हेतु प्रयुक्त होती है?", "Iron (Fe)", "लोहा (Iron / Fe)", ["Silver", "Gold", "Zinc"], ["चांदी", "सोना", "जस्ता"], "Iron does not amalgamate with mercury, hence mercury is shipped in iron flasks.", "लोहा पारे के साथ अमलगम नहीं बनाता, अतः पारे को लोहे के पात्र में रखा जाता है।"),
        ("Modern Periodic Table was organized based on atomic number by", "परमाणु क्रमांक के आधार पर आधुनिक आवर्त सारणी किसने प्रस्तुत की थी?", "Henry Moseley (1913)", "हेनरी मोजले (1913)", ["Dmitri Mendeleev", "John Newlands", "Johann Dobereiner"], ["दिमित्री मेंडेलीव", "जॉन न्यूलैंड्स", "डोबेराइनर"], "Moseley showed that atomic number (Z), not atomic mass, determines periodic properties.", "मोजले ने सिद्ध किया कि तत्वों के गुण परमाणु भार नहीं बल्कि परमाणु क्रमांक के आवर्ती फलन हैं।"),
        ("Dmitri Mendeleev arranged elements in his original 1869 periodic table according to", "दिमित्री मेंडेलीव की मूल आवर्त सारणी (1869) किस आधार पर व्यवस्थित थी?", "Atomic Mass", "परमाणु भार (Atomic Mass)", ["Atomic Number", "Density", "Number of neutrons"], ["परमाणु क्रमांक", "घनत्व", "न्यूट्रॉनों की संख्या"], "Mendeleev left gaps for undiscovered elements like eka-silicon (Germanium).", "मेंडेलीव ने तत्वों को उनके बढ़ते परमाणु भार के आधार पर क्रमबद्ध किया था।"),
        ("How many vertical Groups and horizontal Periods are there in the Modern Periodic Table?", "आधुनिक आवर्त सारणी में कितने ऊर्ध्वाधर वर्ग (Groups) तथा क्षैतिज आवर्त (Periods) हैं?", "18 Groups and 7 Periods", "18 वर्ग (Groups) तथा 7 आवर्त (Periods)", ["16 Groups and 8 Periods", "8 Groups and 7 Periods", "18 Groups and 8 Periods"], ["16 वर्ग तथा 8 आवर्त", "8 वर्ग तथा 7 आवर्त", "18 वर्ग तथा 8 आवर्त"], "Consists of 18 numbered vertical IUPAC columns and 7 horizontal rows.", "आधुनिक आवर्त सारणी में 18 वर्ग (कॉलम) और 7 आवर्त (पंक्तियां) होते हैं।"),
        ("Group 18 elements in the Periodic Table (He, Ne, Ar, Kr, Xe, Rn) are termed", "आवर्त सारणी के वर्ग 18 के तत्वों (He, Ne, Ar, Kr, Xe, Rn) को क्या कहा जाता है?", "Noble Gases / Inert Gases", "उत्कृष्ट गैसें / अक्रिय गैसें (Noble Gases)", ["Halogens", "Alkali Metals", "Alkaline Earth Metals"], ["हैलोजन", "क्षार धातुएं", "क्षारीय मृदा धातुएं"], "Valence shell is completely filled with octet (duplet for He), making them chemically unreactive.", "इनका बाह्यतम कोश पूर्ण भरा होता है, अतः ये अक्रिय या नोबल गैसें कहलाती हैं।"),
        ("Group 17 elements in the Periodic Table (F, Cl, Br, I, At) are termed", "आवर्त सारणी के वर्ग 17 के तत्वों (F, Cl, Br, I, At) को क्या कहते हैं?", "Halogens (Salt formers)", "हैलोजन (Halogens / लवण उत्पादक)", ["Noble gases", "Chalcogens", "Alkali metals"], ["नोबल गैसें", "कैल्कोजन", "क्षार धातुएं"], "Electronegative elements that form salts upon reacting with alkali metals.", "हैलोजन (ग्रीक: लवण बनाने वाले) तीव्र अभिक्रियाशील अधातुएं हैं।"),
        ("Which element is the most electronegative of all elements in the periodic table?", "आवर्त सारणी का सर्वाधिक विद्युत-ऋणात्मक (Electronegative) तत्व कौन सा है?", "Fluorine (F, value 4.0 on Pauling scale)", "फ्लोरीन (F, पॉलिंग पैमाने पर 4.0)", ["Chlorine", "Oxygen", "Nitrogen"], ["क्लोरीन", "ऑक्सीजन", "नाइट्रोजन"], "Fluorine has the highest tendency to attract shared electron pairs.", "फ्लोरीन की विद्युत-ऋणात्मकता पूरे आवर्त सारणी में सर्वाधिक होती है।"),
        ("Which element exhibits the highest electron affinity in the periodic table?", "आवर्त सारणी में सर्वाधिक इलेक्ट्रॉन बंधुता (Electron Affinity) किस तत्व की होती है?", "Chlorine (Cl)", "क्लोरीन (Cl)", ["Fluorine", "Bromine", "Oxygen"], ["फ्लोरीन", "ब्रोमीन", "ऑक्सीजन"], "Chlorine releases more energy upon accepting an electron due to lower valence electron repulsion.", "क्लोरीन में इलेक्ट्रॉन प्रतिकर्षण कम होने से इसकी इलेक्ट्रॉन बंधुता फ्लोरीन से अधिक होती है।"),
        ("Which chemical element is the most abundant element in the Earth's crust by mass?", "पृथ्वी की भूपर्पटी (Crust) में द्रव्यमान के अनुसार सर्वाधिक पाया जाने वाला तत्व कौन सा है?", "Oxygen (~46.6%)", "ऑक्सीजन (लगभग 46.6%)", ["Silicon", "Aluminium", "Iron"], ["सिलिकॉन", "एल्युमिनियम", "लोहा"], "Oxygen constitutes nearly half of Earth's crust minerals, followed by Silicon (~27.7%).", "भूपर्पटी में सर्वाधिक ऑक्सीजन (46.6%) तथा दूसरे स्थान पर सिलिकॉन (27.7%) पाया जाता है।"),
        ("Which metal is the most abundant metal in the Earth's crust?", "पृथ्वी की भूपर्पटी में सर्वाधिक मात्रा में पाई जाने वाली धातु कौन सी है?", "Aluminium (~8.1%)", "एल्युमिनियम (~8.1%)", ["Iron", "Calcium", "Sodium"], ["लोहा", "कैल्शियम", "सोडियम"], "Aluminium is third most abundant element overall and first among metals.", "तत्वों में ऑक्सीजन और सिलिकॉन के बाद धातुओं में एल्युमिनियम सर्वाधिक प्रचुर है।"),
        ("Which gas constitutes the greatest percentage of Earth's atmosphere by volume?", "पृथ्वी के वायुमंडल में आयतन के अनुसार सर्वाधिक मात्रा में कौन सी गैस पाई जाती है?", "Nitrogen (N2, ~78.08%)", "नाइट्रोजन (N2, लगभग 78.08%)", ["Oxygen", "Argon", "Carbon dioxide"], ["ऑक्सीजन", "ऑर्गन", "कार्बन डाइऑक्साइड"], "Nitrogen comprises 78%, Oxygen 20.95%, Argon 0.93%, and CO2 0.04%.", "वायुमंडल में 78% नाइट्रोजन, 21% ऑक्सीजन, 0.93% ऑर्गन तथा 0.04% CO2 होती है।"),
        ("Which noble gas is the most abundant inert gas in Earth's atmosphere?", "पृथ्वी के वायुमंडल में सर्वाधिक मात्रा में पाई जाने वाली अक्रिय गैस कौन सी है?", "Argon (Ar, ~0.93%)", "ऑर्गन (Ar, लगभग 0.93%)", ["Neon", "Helium", "Krypton"], ["नियॉन", "हीलियम", "क्रिप्टॉन"], "Argon is produced primarily by radioactive decay of Potassium-40 in Earth's crust.", "वायुमंडल में अक्रिय गैसों में ऑर्गन की मात्रा सर्वाधिक (0.93%) होती है।"),
        ("What is the typical normal pH of healthy human blood?", "स्वस्थ मानव रक्त का सामान्य pH मान कितना होता है?", "7.35 to 7.45 (slightly alkaline)", "7.35 से 7.45 (हल्का क्षारीय)", ["6.0 to 6.5", "8.0 to 8.5", "7.0 (pure neutral)"], ["6.0 से 6.5", "8.0 से 8.5", "7.0"], "Maintained strictly by bicarbonate carbonic acid buffering system.", "मानव रक्त हल्का क्षारीय होता है और इसका pH मान 7.35 से 7.45 के मध्य रहता है।"),
        ("What is the pH value of pure neutral distilled water at 25°C?", "25°C पर शुद्ध आसुत जल का pH मान कितना होता है?", "7.0", "7.0 (उदासीन)", ["6.0", "8.0", "0.0"], ["6.0", "8.0", "0.0"], "At 25°C, [H+] = [OH-] = 10^-7 M, giving exact pH 7.", "शुद्ध जल उदासीन होता है तथा इसका pH मान ठीक 7.0 होता है।"),
        ("Rainwater is officially classified as 'Acid Rain' when its pH falls below", "वर्षा के जल का pH मान कितने से कम होने पर उसे 'अम्लीय वर्षा' (Acid Rain) कहा जाता है?", "5.6", "5.6", ["6.5", "7.0", "4.0"], ["6.5", "7.0", "4.0"], "Caused by dissolved Sulphur Dioxide (SO2) and Nitrogen Oxides (NOx) forming acids.", "सल्फर और नाइट्रोजन के ऑक्साइड घुलकर सल्फ्यूरिक व नाइट्रिक अम्ल बनाते हैं (pH < 5.6)।"),
        ("What acid is naturally present in lemon, oranges, and amla?", "नींबू एवं संतरे जैसे खट्टे फलों में कौन सा अम्ल प्राकृतिक रूप से पाया जाता है?", "Citric Acid", "साइट्रिक अम्ल (Citric Acid)", ["Acetic acid", "Tartaric acid", "Lactic acid"], ["एसिटिक अम्ल", "टार्टरिक अम्ल", "लैक्टिक अम्ल"], "Citrus fruits contain citric acid and ascorbic acid (Vitamin C).", "खट्टे रसीले फलों में साइट्रिक एसिड पाया जाता है।"),
        ("Which organic acid causes the sour taste in sour milk and curd (yogurt)?", "दही तथा खट्टे दूध में खट्टेपन का कारण कौन सा अम्ल होता है?", "Lactic Acid", "लैक्टिक अम्ल (Lactic Acid)", ["Citric acid", "Formic acid", "Oxalic acid"], ["साइट्रिक अम्ल", "फॉर्मिक अम्ल", "ऑक्सालिक अम्ल"], "Lactobacillus bacteria ferment milk lactose sugar into lactic acid.", "लैक्टोबैसिलस जीवाणु दूध की शर्करा को लैक्टिक एसिड में बदल देते हैं।"),
        ("Which acid is present in tamarind (Imli) and unripened grapes?", "इमली तथा कच्चे अंगूर में कौन सा अम्ल पाया जाता है?", "Tartaric Acid", "टार्टरिक अम्ल (Tartaric Acid)", ["Citric acid", "Malic acid", "Acetic acid"], ["साइट्रिक अम्ल", "मैलिक अम्ल", "एसिटिक अम्ल"], "Tartaric acid gives tamarind its sharp characteristic tart taste.", "इमली में मुख्य रूप से टार्टरिक अम्ल उपस्थित होता है।"),
        ("Which acid is injected by red ants, nettle plants, and bee stings?", "लाल चींटी, मधुमक्खी तथा बिच्छू के डंक में कौन सा अम्ल होता है?", "Formic Acid (Methanoic acid, HCOOH)", "फॉर्मिक अम्ल / मेथेनॉइक अम्ल (HCOOH)", ["Acetic acid", "Oxalic acid", "Benzoic acid"], ["एसिटिक अम्ल", "ऑक्सालिक अम्ल", "बेंजोइक अम्ल"], "Formic acid causes localized burning, itching, and tissue inflammation.", "चींटी व मधुमक्खी के डंक में फॉर्मिक एसिड होता है जो जलन उत्पन्न करता है।"),
        ("Apples primarily contain which organic dicarboxylic fruit acid?", "सेब (Apple) में मुख्य रूप से कौन सा कार्बनिक अम्ल पाया जाता है?", "Malic Acid", "मैलिक अम्ल (Malic Acid)", ["Citric acid", "Tartaric acid", "Lactic acid"], ["साइट्रिक अम्ल", "टार्टरिक अम्ल", "लैक्टिक अम्ल"], "Malic acid is the primary acid giving crisp tartness to apples.", "सेब में मुख्य रूप से मैलिक अम्ल पाया जाता है।"),
        ("Tomatoes and spinach contain which organic acid that can form kidney stones?", "टमाटर एवं पालक में कौन सा अम्ल पाया जाता है जो गुर्दे की पथरी बना सकता है?", "Oxalic Acid", "ऑक्सालिक अम्ल (Oxalic Acid)", ["Citric acid", "Malic acid", "Tartaric acid"], ["साइट्रिक अम्ल", "मैलिक अम्ल", "टार्टरिक अम्ल"], "Oxalic acid binds with calcium to form insoluble calcium oxalate kidney stones.", "ऑक्सालिक अम्ल कैल्शियम से मिलकर कैल्शियम ऑक्सालेट की पथरी बनाता है।"),
        ("Gastric juice produced in human stomach contains which digestive mineral acid?", "मानव आमाशय (Stomach) के जठर रस में कौन सा पाचक अम्ल स्रावित होता है?", "Hydrochloric Acid (HCl)", "हाइड्रोक्लोरिक अम्ल (HCl)", ["Sulphuric acid", "Nitric acid", "Acetic acid"], ["सल्फ्यूरिक अम्ल", "नाइट्रिक अम्ल", "एसिटिक अम्ल"], "HCl (pH ~1.5 to 2.0) kills ingested bacteria and activates pepsinogen enzyme.", "आमाशय की भित्तियां HCl स्रावित करती हैं जो भोजन के जीवाणुओं को मारता है।"),
        ("Acid turns blue litmus paper into which color?", "अम्ल नीले लिटमस पत्र को किस रंग में बदल देता है?", "Red", "लाल (Red)", ["Blue", "Green", "Yellow"], ["नीला", "हरा", "पीला"], "Acids turn blue litmus red; bases turn red litmus blue.", "अम्ल नीले लिटमस को लाल कर देता है, जबकि क्षार लाल लिटमस को नीला करता है।"),
        ("A basic (alkaline) solution turns phenolphthalein indicator into which color?", "क्षारीय विलयन में फिनॉल्फथलीन सूचक का रंग कैसा हो जाता है?", "Pink", "गुलाबी (Pink)", ["Colorless", "Yellow", "Blue"], ["रंगहीन", "पीला", "नीला"], "Phenolphthalein turns bright magenta-pink in bases and stays colorless in acids.", "फिनॉल्फथलीन अम्ल में रंगहीन तथा क्षार में गहरा गुलाबी हो जाता है।"),
        ("Galvanization of iron sheets to prevent rusting involves applying a protective coating of", "लोहे को जंग से बचाने के लिए उस पर जस्ते की परत चढ़ाना (Galvanization) क्या कहलाता है?", "Zinc (Zn)", "जस्ता / जिंक (Zn)", ["Tin", "Copper", "Lead"], ["टिन", "तांबा", "सीसा"], "Zinc acts as a sacrificial anode, corroding in preference to underlying iron.", "जस्तीकरण (Galvanization) में लोहे पर जस्ते (जिंक) की परत चढ़ाई जाती है।"),
        ("The reddish-brown flaky coating formed during rusting of iron is chemically", "लोहे पर लगने वाली जंग (Rust) रासायनिक रूप से क्या होती है?", "Hydrated Ferric Oxide (Fe2O3.xH2O)", "जलयोजित फेरिक ऑक्साइड (Fe2O3.xH2O)", ["Ferrous oxide (FeO)", "Magnetic iron oxide (Fe3O4)", "Iron carbonate"], ["फेरस ऑक्साइड", "चुंबकीय ऑक्साइड", "आयरन कार्बोनेट"], "Iron reacts with oxygen and atmospheric water vapor to form hydrated iron(III) oxide.", "लोहे में जंग लगना एक ऑक्सीकरण क्रिया है जिससे जलयोजित फेरिक ऑक्साइड बनता है।"),
        ("When iron rusts, what happens to the total weight of the iron object?", "जब लोहे में जंग लग जाती है, तो उसके कुल भार पर क्या प्रभाव पड़ता है?", "Increases (due to added oxygen and water molecules)", "भार बढ़ जाता है (ऑक्सीजन व जल जुड़ने के कारण)", ["Decreases", "Remains unchanged", "Fluctuates up and down"], ["घट जाता है", "अपरिवर्तित रहता है", "घटता-बढ़ता है"], "Oxygen and water chemically bind into the iron matrix, increasing net mass.", "लोहा पर्यावरण की ऑक्सीजन और नमी ग्रहण करता है, अतः जंग लगने पर भार बढ़ता है।"),
        ("Bauxite is the principal industrial ore used for extracting which metal?", "बॉक्साइट (Bauxite) किस धातु का प्रमुख खनिज अयस्क है?", "Aluminium (Al)", "एल्युमिनियम (Al)", ["Iron", "Copper", "Zinc"], ["लोहा", "तांबा", "जस्ता"], "Bauxite (Al2O3.2H2O) is processed via Bayer process and Hall-Héroult electrolysis.", "बॉक्साइट एल्युमिनियम का सबसे महत्वपूर्ण प्राकृतिक अयस्क है।"),
        ("Haematite and Magnetite are the primary mineral ores of", "हेमेटाइट तथा मैग्नेटाइट किस धातु के प्रमुख अयस्क हैं?", "Iron (Fe)", "लोहा (Iron / Fe)", ["Copper", "Aluminium", "Lead"], ["तांबा", "एल्युमिनियम", "सीसा"], "Haematite is Fe2O3 and Magnetite is natural black magnetic ore Fe3O4.", "हेमेटाइट (Fe2O3) तथा मैग्नेटाइट (Fe3O4) लोहे के प्रमुख अयस्क हैं।"),
        ("Cinnabar (Hingul) is the natural mineral ore of which toxic heavy metal?", "सिनाबार / हिंगुल (Cinnabar) किस भारी धातु का अयस्क है?", "Mercury (HgS)", "पारा / मरकरी (HgS)", ["Lead", "Copper", "Arsenic"], ["सीसा", "तांबा", "आर्सेनिक"], "Cinnabar is mercuric sulphide (HgS), roasted to extract elemental mercury.", "सिनाबार मर्क्यूरिक सल्फाइड (HgS) है जिससे पारा निष्कर्षित किया जाता है।"),
        ("Galena is the principal natural ore of which metal?", "गैलेना (Galena) किस धातु का प्रमुख अयस्क है?", "Lead (PbS)", "सीसा / लेड (PbS)", ["Tin", "Zinc", "Iron"], ["टिन", "जस्ता", "लोहा"], "Galena is lead(II) sulphide (PbS), the primary ore of commercial lead.", "गैलेना लेड सल्फाइड (PbS) है, जो सीसे का प्रमुख खनिज है।"),
        ("Carnallite and Dolomite are important natural mineral ores containing", "कार्नेलाइट तथा डोलोमाइट किस धातु के महत्वपूर्ण अयस्क हैं?", "Magnesium (Mg)", "मैग्नीशियम (Mg)", ["Calcium only", "Copper", "Aluminium"], ["केवल कैल्शियम", "तांबा", "एल्युमिनियम"], "Dolomite is CaCO3.MgCO3; Carnallite is KCl.MgCl2.6H2O.", "डोलोमाइट (CaCO3.MgCO3) मैग्नीशियम का प्रमुख अयस्क है।"),
        ("Pitchblende is the radioactive uranium-rich mineral ore from which which element was discovered?", "पिचब्लेंड (Pitchblende) अयस्क से मैडम क्यूरी ने किस रेडियोधर्मी तत्व की खोज की थी?", "Radium and Polonium", "रेडियम एवं पोलोनियम (Radium & Polonium)", ["Thorium", "Plutonium", "Neptunium"], ["थोरियम", "प्लूटोनियम", "नेप्च्यूनियम"], "Marie and Pierre Curie separated radium and polonium from pitchblende in 1898.", "मैरी क्यूरी और पियरे क्यूरी ने पिचब्लेंड से रेडियम और पोलोनियम को अलग किया था।"),
        ("Monazite sand found in abundance on the beaches of Kerala is a rich source of", "केरल के समुद्री तटों की मोनाजाइट रेत किस महत्वपूर्ण तत्व का समृद्ध स्रोत है?", "Thorium (Th)", "थोरियम (Thorium)", ["Uranium", "Titanium", "Gold"], ["यूरेनियम", "टाइटेनियम", "सोना"], "India possesses ~25% of the world's thorium reserves in beach placer sands.", "भारत में विश्व का सबसे बड़ा थोरियम भंडार केरल के तटीय मोनाजाइट रेत में है।"),
        ("Which gas was released during the catastrophic Bhopal Gas Tragedy (1984)?", "भोपाल गैस त्रासदी (1984) में यूनियन कार्बाइड कारखाने से कौन सी विषैली गैस रिसी थी?", "Methyl Isocyanate (MIC, CH3NCO)", "मिथाइल आइसोसाइनेट (MIC, CH3NCO)", ["Phosgene", "Carbon monoxide", "Chlorine"], ["फॉस्जीन", "कार्बन मोनोक्साइड", "क्लोरीन"], "Leak on night of 2-3 Dec 1984 killed thousands in world's worst industrial disaster.", "2-3 दिसंबर 1984 की रात भोपाल में मिथाइल आइसोसाइनेट (MIC) गैस का रिसाव हुआ था।")
    ]
