    # Q140: Plant Biology & Environmental Ecology (48 distinct questions)
    plant_pool = [
        ("The light-dependent reaction phase of photosynthesis takes place inside the", "प्रकाश संश्लेषण की प्रकाश-अभिक्रिया (Light Reaction) हरितलवक में कहाँ संपन्न होती है?", "Thylakoids / Grana of Chloroplasts", "हरितलवक के थाइलेकॉइड / ग्रेना (Grana) में", ["Stroma", "Outer membrane", "Mitochondrial matrix"], ["स्ट्रोमा (पीठिका)", "बाहरी झिल्ली", "माइटोकॉन्ड्रिया"], "Photolysis of water and ATP/NADPH synthesis occur in the thylakoid membrane.", "जल का प्रकाशीय अपघटन और ऊर्जा निर्माण ग्रेना में होता है।"),
        ("The light-independent dark reaction (Calvin Cycle) of photosynthesis takes place in", "प्रकाश संश्लेषण की अप्रकाशीय अभिक्रिया (केल्विन चक्र) कहाँ संपन्न होती है?", "Stroma of Chloroplasts", "हरितलवक के स्ट्रोमा (Stroma) में", ["Grana", "Thylakoid lumen", "Cell wall"], ["ग्रेना", "थाइलेकॉइड अवकाशिका", "कोशिका भित्ति"], "Enzyme RuBisCO fixes atmospheric CO2 into glucose sugars inside the stroma.", "स्ट्रोमा में RuBisCO एंजाइम द्वारा CO2 का स्थिरीकरण कर ग्लूकोज बनता है।"),
        ("Which enzyme is the most abundant protein on Earth, catalyzing photosynthetic carbon fixation?", "प्रकाश संश्लेषण में कार्बन स्थिरीकरण करने वाला पृथ्वी का सबसे प्रचुर प्रोटीन एंजाइम कौन सा है?", "RuBisCO", "रूबिस्को (RuBisCO)", ["DNA Polymerase", "Amylase", "Pepsin"], ["डीएनए पॉलिमरेज", "एमाइलेज", "पेप्सिन"], "Ribulose-1,5-bisphosphate carboxylase-oxygenase fixes inorganic carbon into organic sugar.", "रूबिस्को (RuBisCO) पौधे में CO2 को पकड़कर शर्करा बनाने वाला मुख्य एंजाइम है।"),
        ("What gas is released as a byproduct during the light reaction of photosynthesis?", "प्रकाश संश्लेषण के दौरान उप-उत्पाद के रूप में कौन सी गैस विमुक्त होती है?", "Oxygen (O2, derived from photolysis of water)", "ऑक्सीजन (O2, जल के प्रकाशीय अपघटन से)", ["Carbon dioxide", "Nitrogen", "Methane"], ["कार्बन डाइऑक्साइड", "नाइट्रोजन", "मेथेन"], "Oxygen evolved comes from splitting H2O molecules, not from carbon dioxide.", "प्रकाश संश्लेषण में निकलने वाली ऑक्सीजन CO2 से नहीं बल्कि जल के अणुओं से आती है।"),
        ("Which plant tissue is responsible for bidirectional transport of photosynthesized food / sucrose?", "पौधों में पत्तियों द्वारा निर्मित भोजन (सुक्रोज) का संवहन कौन सा ऊतक करता है?", "Phloem", "फ्लोएम (Phloem)", ["Xylem", "Cortex", "Epidermis"], ["जाइलम", "कॉर्टेक्स", "बाह्यत्वचा"], "Sieve tubes and companion cells translocate sugars from source leaves to sink tissues.", "फ्लोएम पत्तियों से भोजन को पौधे के विभिन्न भागों तक पहुंचाता है।"),
        ("Which plant vascular tissue conducts water and dissolved mineral nutrients upwards from roots?", "पौधों में जड़ों से जल तथा खनिज लवणों का ऊपर संवहन कौन सा संवहनी ऊतक करता है?", "Xylem", "जाइलम (Xylem)", ["Phloem", "Pith", "Periderm"], ["फ्लोएम", "मज्जा", "परित्वक"], "Tracheids and vessels transport water via transpirational suction pull.", "जाइलम ऊतक जड़ों से पानी और खनिज लवणों को पत्तियों तक पहुंचाता है।"),
        ("Which plant hormone is primarily responsible for cell elongation and apical dominance?", "पौधों में कोशिका दीर्घीकरण तथा शीर्ष प्रमुखता (Apical Dominance) हेतु कौन सा हार्मोन उत्तरदायी है?", "Auxin (e.g. Indole-3-acetic acid, IAA)", "ऑक्सिन / Auxin (जैसे IAA)", ["Gibberellin", "Cytokinin", "Abscisic Acid"], ["जिबरेलिन", "साइटोकाइनिन", "एब्सिसिक एसिड"], "Synthesized at shoot tips; promotes phototropic bending towards light.", "शीर्ष कलिका में बनने वाला ऑक्सिन तने की वृद्धि और प्रकाश की ओर मुड़ने को प्रेरित करता है।"),
        ("Which plant hormone breaks seed dormancy and promotes stem elongation / bolting?", "बीज की प्रसुप्ति तोड़ने तथा तने की लंबाई बढ़ाने वाला पादप हार्मोन कौन सा है?", "Gibberellin (Gibberellic acid, GA)", "जिबरेलिन (Gibberellin / GA)", ["Auxin", "Abscisic Acid", "Ethylene"], ["ऑक्सिन", "एब्सिसिक एसिड", "एथिलीन"], "Discovered in Japan in rice fungus Gibberella fujikuroi causing foolish seedling disease.", "जिबरेलिन बीज अंकुरण और बौने पौधों की लंबाई बढ़ाने में मदद करता है।"),
        ("Which phytohormone actively promotes rapid cell division and delays leaf senescence?", "कोशिका विभाजन को तीव्र करने तथा पत्तियों के बुढ़ापे (Senescence) को रोकने वाला हार्मोन कौन सा है?", "Cytokinin (Zeatin)", "साइटोकाइनिन / Zeatin (Cytokinin)", ["Abscisic Acid", "Ethylene", "Auxin"], ["एब्सिसिक एसिड", "एथिलीन", "ऑक्सिन"], "Promotes cytokinesis and lateral bud outgrowth over apical dominance.", "साइटोकाइनिन कोशिका विभाजन को बढ़ाता है और पत्तियों को हरा बनाए रखता है।"),
        ("Which plant hormone acts as a 'Stress Hormone', inducing stomatal closure and dormancy?", "'तनाव हार्मोन' (Stress Hormone) जो रंध्रों को बंद कर वाष्पोत्सर्जन रोकता है, कौन सा है?", "Abscisic Acid (ABA)", "एब्सिसिक अम्ल / ABA (Abscisic Acid)", ["Gibberellin", "Auxin", "Cytokinin"], ["जिबरेलिन", "ऑक्सिन", "साइटोकाइनिन"], "Inhibits growth during drought, closing stomata to conserve water.", "सूखे की स्थिति में एब्सिसिक एसिड रंध्रों को बंद कर जल हानि रोकता है।"),
        ("Which plant hormone is the only gaseous hormone, promoting the natural ripening of fruits?", "फलों को प्राकृतिक रूप से पकाने वाला एकमात्र गैसीय पादप हार्मोन कौन सा है?", "Ethylene (C2H4)", "एथिलीन / Ethylene (C2H4)", ["Auxin", "Gibberellin", "Cytokinin"], ["ऑक्सिन", "जिबरेलिन", "साइटोकाइनिन"], "Diffusible gas that triggers fruit ripening, abscission of leaves, and flower fading.", "एथिलीन एक गैसीय हार्मोन है जो कच्चे फलों को पकाने का कार्य करता है।"),
        ("Artificial chemical ripening of raw fruits like bananas and mangoes is commercially done using", "कच्चे फलों (केले, आम) को कृत्रिम रूप से पकाने हेतु किस रसायन का उपयोग होता है?", "Calcium Carbide (releasing Acetylene gas) / Ethephon", "कैल्शियम कार्बाइड (एसिटिलीन गैस मुक्त कर) / एथेफॉन", ["Sodium chloride", "Baking powder", "Potassium nitrate"], ["सोडियम क्लोराइड", "बेकिंग पाउडर", "पोटैशियम नाइट्रेट"], "Calcium carbide reacts with moisture releasing acetylene gas, analogous to ethylene.", "कैल्शियम कार्बाइड नमी से क्रिया कर एसिटिलीन गैस बनाता है जो फल पकाती है।"),
        ("Insectivorous pitcher plants (Nepenthes, Drosera) trap and digest insects primarily to obtain", "कीटभक्षी पौधे (घटपर्णी / नेपेंथीस) कीटों का भक्षण मुख्यतः किसकी कमी पूरी करने के लिए करते हैं?", "Nitrogen (in nitrogen-deficient soils)", "नाइट्रोजन (नाइट्रोजन की कमी वाले दलदली क्षेत्रों में)", ["Carbon", "Phosphorus", "Water"], ["कार्बन", "फॉस्फोरस", "जल"], "Digestive proteases break down insect proteins to extract nitrogen in acidic bogs.", "कीटभक्षी पौधे दलदली मिट्टी में नाइट्रोजन की कमी को कीटों को पचाकर पूरा करते हैं।"),
        ("Leguminous plants harbor which symbiotic nitrogen-fixing bacteria in their root nodules?", "दलहनी फसलों की जड़ों की ग्रंथियों में नाइट्रोजन स्थिरीकरण करने वाला कौन सा सहजीवी जीवाणु रहता है?", "Rhizobium", "राइजोबियम (Rhizobium)", ["Azotobacter", "Clostridium", "Pseudomonas"], ["एजोटोबैक्टर", "क्लोस्ट्रीडियम", "स्यूडोमोनास"], "Rhizobium converts atmospheric N2 into ammonia utilizing enzyme nitrogenase.", "राइजोबियम वायुमंडलीय नाइट्रोजन को अमोनिया में बदलकर मृदा को उपजाऊ बनाता है।"),
        ("Lichens represent a textbook mutualistic symbiotic association between", "लाइकेन (Lichens) किन दो सजीवों के मध्य सहजीवी (Symbiotic) संबंध को दर्शाते हैं?", "Algae and Fungi", "शैवाल एवं कवक (Algae and Fungi)", ["Fungi and Roots", "Algae and Bacteria", "Fungi and Ferns"], ["कवक एवं जड़ें", "शैवाल एवं जीवाणु", "कवक एवं फर्न"], "Alga produces carbohydrates via photosynthesis, fungus provides shelter and water absorption.", "शैवाल भोजन बनाता है और कवक जल व आश्रय प्रदान करता है; यह प्रदूषण संकेतक है।"),
        ("Lichens are highly sensitive bio-indicators used to detect environmental pollution of", "लाइकेन (Lichens) किस वायु प्रदूषक के प्रति अत्यधिक संवेदनशील प्राकृतिक संकेतक हैं?", "Sulphur Dioxide (SO2)", "सल्फर डाइऑक्साइड (SO2)", ["Carbon monoxide", "Carbon dioxide", "Methane"], ["कार्बन मोनोक्साइड", "कार्बन डाइऑक्साइड", "मेथेन"], "Lichens vanish rapidly in industrial areas having high ambient SO2 levels.", "हवा में SO2 का प्रदूषण बढ़ते ही लाइकेन नष्ट हो जाते हैं, अतः ये वायु प्रदूषक सूचक हैं।"),
        ("Mycorrhiza is a beneficial mutualistic symbiotic partnership between", "माइकोराइजा (Mycorrhiza) किनके मध्य परस्पर लाभकारी सहजीवी साझेदारी है?", "Fungi and Roots of higher plants (e.g. Pinus)", "कवक एवं उच्च पादपों की जड़ें (जैसे चीड़)", ["Algae and Fungi", "Bacteria and Viruses", "Bryophytes and Ferns"], ["शैवाल एवं कवक", "जीवाणु एवं विषाणु", "मॉस एवं फर्न"], "Fungal hyphae absorb soil phosphorus and water, plant supplies photosynthetic sugars.", "कवक पौधे को फॉस्फोरस व जल सोखकर देता है और पौधा कवक को भोजन देता है।"),
        ("The international Ramsar Convention signed in 1971 in Iran is dedicated to the conservation of", "1971 में ईरान में हस्ताक्षरित 'रामसर सम्मेलन' (Ramsar Convention) किसके संरक्षण से संबंधित है?", "Wetlands (Wetland ecosystems)", "आर्द्रभूमियां / नमभूमियां (Wetlands)", ["Tropical rainforests", "Coral reefs", "Ozone layer"], ["उष्णकटिबंधीय वर्षावन", "प्रवाल भित्तियां", "ओजोन परत"], "Designates Ramsar Sites for wetland biodiversity; World Wetlands Day is 2nd February.", "रामसर सम्मेलन विश्व भर के महत्वपूर्ण आर्द्रभूमि (वेटलैंड) क्षेत्रों का संरक्षण करता है।"),
        ("The international Montreal Protocol signed in 1987 was established to phase out substances that", "1987 का ऐतिहासिक 'मॉन्ट्रियल प्रोटोकॉल' (Montreal Protocol) किसके संरक्षण हेतु हस्ताक्षरित हुआ था?", "Deplete the Stratospheric Ozone Layer (CFCs, Halons)", "समताप मंडल की ओजोन परत को नुकसान पहुंचाने वाले पदार्थों (CFCs) का उन्मूलन", ["Cause global warming CO2", "Toxic hazardous waste export", "Endangered species hunting"], ["ग्रीनहाउस गैसें", "खतरनाक कचरा", "लुप्तप्राय प्रजातियां"], "Successfully phased out chlorofluorocarbons (CFCs) protecting Earth's ozone layer.", "ओजोन परत को नष्ट करने वाले क्लोरोफ्लोरोकार्बन (CFC) के उत्पादन पर रोक लगाई।"),
        ("The Kyoto Protocol adopted in 1997 under UNFCCC commits industrialized nations to reduce", "1997 का 'क्योटो प्रोटोकॉल' (Kyoto Protocol) मुख्य रूप से किससे संबंधित है?", "Greenhouse Gas Emissions (combating Climate Change)", "ग्रीनहाउस गैसों के उत्सर्जन में कमी (जलवायु परिवर्तन)", ["Ozone depleting chemicals", "Nuclear weapons testing", "Ocean plastic pollution"], ["ओजोन क्षयकारी रसायन", "परमाणु परीक्षण", "समुद्री प्लास्टिक"], "Sets binding reduction targets on 6 major greenhouse gases (CO2, CH4, N2O, HFCs, PFCs, SF6).", "ग्लोबल वार्मिंग रोकने के लिए ग्रीनहाउस गैसों के उत्सर्जन में कमी लाने का वैश्विक समझौता।"),
        ("Which gas contributes the greatest percentage to the natural greenhouse effect on Earth?", "पृथ्वी पर प्राकृतिक ग्रीनहाउस प्रभाव में सर्वाधिक प्रतिशत योगदान किस गैस का है?", "Water Vapor (H2O, ~36-70%) followed by Carbon Dioxide", "जलवाष्प (Water Vapor, लगभग 50-70%)", ["Methane", "Ozone", "Nitrous oxide"], ["मेथेन", "ओजोन", "नाइट्रस ऑक्साइड"], "Water vapor contributes ~50% and CO2 ~25% of Earth's atmospheric thermal blanket.", "ग्रीनहाउस प्रभाव में सबसे बड़ा हिस्सा जलवाष्प (बादलों सहित) का होता है, फिर CO2 का।"),
        ("The primary atmospheric pollutant gases responsible for forming Acid Rain are", "अम्लीय वर्षा (Acid Rain) के लिए उत्तरदायी प्रमुख वायुमंडलीय प्रदूषक गैसें कौन सी हैं?", "Sulphur Dioxide (SO2) and Nitrogen Dioxide (NO2)", "सल्फर डाइऑक्साइड (SO2) एवं नाइट्रोजन डाइऑक्साइड (NO2)", ["Carbon monoxide and Methane", "Carbon dioxide and Oxygen", "Chlorofluorocarbons and Ozone"], ["कार्बन मोनोक्साइड", "CO2 एवं O2", "CFC एवं ओजोन"], "React with water vapor forming sulphuric acid (H2SO4) and nitric acid (HNO3).", "कारखानों से निकली SO2 और NO2 वर्षा जल से क्रिया कर सल्फ्यूरिक व नाइट्रिक अम्ल बनाती हैं।"),
        ("Photochemical Smog (Los Angeles smog) is an oxidizing haze characterized by high levels of", "प्रकाश-रासायनिक धूम-कोहरा (Photochemical Smog) में मुख्य रूप से क्या उपस्थित होता है?", "Ozone (O3), PAN (Peroxyacetyl nitrate), and Nitrogen Oxides", "ओजोन (O3), पैन (PAN) तथा नाइट्रोजन के ऑक्साइड", ["Sulphur dioxide and smoke", "Pure water fog", "Carbon monoxide alone"], ["SO2 एवं धुआं", "केवल जल कोहरा", "केवल कार्बन मोनोक्साइड"], "Sunlight reacts with vehicular NOx and volatile organic compounds (VOCs).", "सूर्य के प्रकाश में नाइट्रोजन ऑक्साइड तथा हाइड्रोकार्बन मिलकर ओजोन व PAN बनाते हैं।"),
        ("The 10% Law of Energy Transfer between successive trophic levels in an ecosystem was formulated by", "पारिस्थितिक तंत्र में एक पोषण स्तर से दूसरे में '10% ऊर्जा स्थानांतरण का नियम' किसने दिया था?", "Raymond Lindeman (1942)", "रेमंड लिंडमैन (Raymond Lindeman, 1942)", ["Ernst Haeckel", "Arthur Tansley", "Eugene Odum"], ["अर्न्स्ट हैकल", "आर्थर टांसले", "ओडम"], "Only ~10% of energy is transferred to the next level; 90% lost as metabolic heat.", "लिंडमैन के अनुसार प्रत्येक पोषण स्तर पर केवल 10% ऊर्जा ही आगे संचरित होती है।"),
        ("Who coined the fundamental ecological term 'Ecosystem' in 1935?", "1935 में 'पारिस्थितिक तंत्र' (Ecosystem) शब्द का सर्वप्रथम प्रयोग किसने किया था?", "Arthur Tansley (A.G. Tansley)", "आर्थर टांसले (A.G. Tansley)", ["Ernst Haeckel", "Charles Elton", "Eugene Odum"], ["अर्न्स्ट हैकल", "चार्ल्स एल्टन", "ओडम"], "Tansley integrated biotic communities with their abiotic physical environment.", "ए.जी. टांसले ने 1935 में जैविक और अजैविक घटकों के तंत्र को 'इकोसिस्टम' कहा।"),
        ("Who coined the term 'Ecology' (Oekologie) in 1866?", "1866 में 'पारिस्थितिकी' (Ecology) शब्द का प्रतिपादन किसने किया था?", "Ernst Haeckel", "अर्न्स्ट हैकल (Ernst Haeckel)", ["Arthur Tansley", "Charles Darwin", "Gregor Mendel"], ["आर्थर टांसले", "चार्ल्स डार्विन", "मेंडल"], "Derived from Greek 'oikos' (household/dwelling place) and 'logos' (study).", "जर्मन जीवविज्ञानी अर्न्स्ट हैकल ने जीवों और पर्यावरण के अध्ययन को इकोलॉजी कहा।"),
        ("In an ecological pyramid, which trophic level always occupies the base?", "पारिस्थितिक पिरामिड के आधार पर सदैव कौन सा पोषण स्तर स्थित होता है?", "Primary Producers (Autotrophic green plants / Phytoplankton)", "प्राथमिक उत्पादक (स्वपोषी हरे पौधे / पादप प्लवक)", ["Primary consumers", "Secondary consumers", "Apex predators"], ["प्राथमिक उपभोक्ता", "द्वितीयक उपभोक्ता", "शीर्ष शिकारी"], "Autotrophs convert solar energy into chemical biomass supporting all higher levels.", "हरे पौधे सौर ऊर्जा से भोजन बनाते हैं, अतः ये पिरामिड के आधार पर स्थित होते हैं।"),
        ("The ecological Pyramid of Energy is always", "पारिस्थितिक तंत्र में ऊर्जा का पिरामिड (Pyramid of Energy) सदैव कैसा होता है?", "Always Upright (never inverted)", "सदैव सीधा (Always Upright / कभी उलटा नहीं)", ["Always inverted", "Spindle shaped", "Inverted in aquatic systems"], ["सदैव उलटा", "तर्कुरूप", "जलीय में उलटा"], "Energy continuously dissipates as heat according to thermodynamics, diminishing upwards.", "ऊष्मागतिकी के नियमानुसार ऊर्जा हर स्तर पर घटती है, अतः ऊर्जा पिरामिड सदैव सीधा होता है।"),
        ("Chipko Movement, a grassroots forest conservation movement launched in 1973 in Uttarakhand, was led by", "1973 में उत्तराखंड में शुरू हुए प्रसिद्ध 'चिपको आंदोलन' के प्रमुख प्रणेता कौन थे?", "Sunderlal Bahuguna and Chandi Prasad Bhatt", "सुंदरलाल बहुगुणा एवं चंडी प्रसाद भट्ट", ["Medha Patkar", "Baba Amte", "Salim Ali"], ["मेधा पाटकर", "बाबा आमटे", "सलीम अली"], "Villagers hugged trees to prevent commercial logging; slogan 'Ecology is permanent economy'.", "ग्रामीणों ने पेड़ों से चिपककर उनकी कटाई रोकी थी; 'पारिस्थितिकी ही स्थायी अर्थव्यवस्था है'।"),
        ("Narmada Bachao Andolan (NBA) environmental movement was spearheaded by", "'नर्मदा बचाओ आंदोलन' (NBA) का नेतृत्व किसने किया था?", "Medha Patkar and Baba Amte", "मेधा पाटकर एवं बाबा आमटे (Medha Patkar)", ["Sunderlal Bahuguna", "Vandana Shiva", "Sunita Narain"], ["सुंदरलाल बहुगुणा", "वंदना शिवा", "सुनीता नारायण"], "Protested against massive displacement caused by Sardar Sarovar Dam on Narmada River.", "सरदार सरोवर बांध के विस्थापन और पर्यावरणीय प्रभाव के विरुद्ध आंदोलन चलाया।"),
        ("Silent Valley Movement in Kerala (1970s) was organized to protect evergreen rainforests from a", "केरल में 'साइलेंट वैली आंदोलन' किस परियोजना के विरुद्ध वन बचाने हेतु चलाया गया था?", "Hydroelectric Dam across the Kunthipuzha River", "कुंतीपुझा नदी पर जलविद्युत बांध परियोजना", ["Highway expressway", "Bauxite mining", "Thermal power plant"], ["राजमार्ग निर्माण", "बॉक्साइट खनन", "तापीय विद्युत संयंत्र"], "Successfully preserved biodiversity of Silent Valley, later declared a National Park in 1984.", "सदाबहार वर्षावन और लुप्तप्राय शेर-पूंछ वाले मकाक बंदरों के संरक्षण हेतु सफल आंदोलन।"),
        ("Appiko Movement, a Southern Indian forest conservation movement inspired by Chipko, started in", "चिपको आंदोलन से प्रेरित होकर दक्षिण भारत में 'एपिको आंदोलन' किस राज्य में प्रारंभ हुआ था?", "Karnataka (Uttara Kannada district in 1983)", "कर्नाटक (उत्तर कन्नड़ जिला, 1983)", ["Tamil Nadu", "Kerala", "Andhra Pradesh"], ["तमिलनाडु", "केरल", "आंध्र प्रदेश"], "Pandurang Hegde led villagers to hug trees in Western Ghats to halt deforestation.", "पांडुरंग हेगड़े के नेतृत्व में पश्चिमी घाट के वनों को बचाने हेतु आंदोलन चला।"),
        ("Project Tiger in India was launched by the Government of India in", "भारत सरकार द्वारा 'प्रोजेक्ट टाइगर' (Project Tiger) किस वर्ष प्रारंभ किया गया था?", "1973 (at Jim Corbett National Park)", "1973 में (जिम कॉर्बेट राष्ट्रीय उद्यान से)", ["1980", "1992", "1971"], ["1980 में", "1992 में", "1971 में"], "Launched by PM Indira Gandhi; celebrated 50 years in 2023 with tiger population >3,167.", "बाघों के संरक्षण हेतु 1 अप्रैल 1973 को जिम कॉर्बेट पार्क से प्रोजेक्ट टाइगर शुरू हुआ।"),
        ("Project Elephant was launched by the Ministry of Environment and Forests in India in", "भारत में हाथियों के संरक्षण हेतु 'प्रोजेक्ट एलीफेंट' (Project Elephant) किस वर्ष शुरू हुआ?", "1992", "1992 में (1992)", ["1973", "2000", "1985"], ["1973", "2000", "1985"], "Protects elephant corridors, mitigates human-elephant conflict, and ensures welfare.", "हाथियों के प्राकृतिक आवास और गलियारों की सुरक्षा हेतु 1992 में शुरू किया गया।"),
        ("Wildlife Protection Act of India was enacted in which year?", "भारत का 'वन्यजीव संरक्षण अधिनियम' (Wildlife Protection Act) किस वर्ष पारित हुआ था?", "1972", "1972 में (1972)", ["1980", "1986", "1974"], ["1980", "1986", "1974"], "Provides legal framework for establishing National Parks, Sanctuaries, and penalizing poaching.", "राष्ट्रीय उद्यानों की स्थापना और शिकार पर प्रतिबंध हेतु 1972 में कानून बना।"),
        ("Environment (Protection) Act of India was enacted in which year after the Bhopal gas tragedy?", "भोपाल गैस कांड की पृष्ठभूमि में भारत का 'पर्यावरण संरक्षण अधिनियम' किस वर्ष लागू हुआ?", "1986", "1986 में (1986)", ["1981", "1974", "1991"], ["1981", "1974", "1991"], "Enacted under Article 253 of the Constitution to protect and improve the environment.", "पर्यावरण की सुरक्षा और सुधार हेतु संविधान के अनुच्छेद 253 के तहत 1986 में बना।"),
        ("Forest (Conservation) Act of India was enacted in", "भारत का 'वन संरक्षण अधिनियम' (Forest Conservation Act) किस वर्ष लागू किया गया था?", "1980", "1980 में (1980)", ["1972", "1986", "1952"], ["1972", "1986", "1952"], "Restricts diversion of forest lands for non-forest commercial purposes without central approval.", "वनों के गैर-वानिकी उपयोग को रोकने के लिए 1980 में यह अधिनियम पारित हुआ।"),
        ("Water (Prevention and Control of Pollution) Act in India was enacted in", "भारत का 'जल (प्रदूषण निवारण एवं नियंत्रण) अधिनियम' किस वर्ष पारित हुआ था?", "1974", "1974 में (1974)", ["1981", "1986", "1972"], ["1981", "1986", "1972"], "Established the Central Pollution Control Board (CPCB) and State Pollution Control Boards.", "प्रदूषण नियंत्रण बोर्डों (CPCB) की स्थापना इसी 1974 के जल अधिनियम द्वारा हुई।"),
        ("Air (Prevention and Control of Pollution) Act of India was enacted in", "भारत का 'वायु (प्रदूषण निवारण एवं नियंत्रण) अधिनियम' किस वर्ष पारित हुआ था?", "1981", "1981 में (1981)", ["1974", "1986", "1990"], ["1974", "1986", "1990"], "Amended in 1987 to include 'Noise Pollution' within the definition of air pollutants.", "1981 में बना; 1987 में संशोधन कर ध्वनि प्रदूषण को भी वायु प्रदूषण में शामिल किया गया।"),
        ("National Green Tribunal (NGT) of India was established under the NGT Act in", "भारत में 'राष्ट्रीय हरित अधिकरण' (NGT) की स्थापना किस वर्ष की गई थी?", "2010", "2010 में (2010)", ["2002", "2005", "2015"], ["2002", "2005", "2015"], "Specialized fast-track environmental court headquartered in New Delhi.", "पर्यावरणीय मामलों के त्वरित निपटारे हेतु 2010 में NGT की स्थापना हुई।"),
        ("Which Indian state has the highest percentage of forest cover relative to its geographical area?", "भौगोलिक क्षेत्रफल के प्रतिशत के अनुसार भारत के किस राज्य में सर्वाधिक वनावरण है?", "Mizoram (~84.5%)", "मिजोरम (लगभग 84.5%)", ["Arunachal Pradesh", "Meghalaya", "Madhya Pradesh"], ["अरुणाचल प्रदेश", "मेघालय", "मध्य प्रदेश"], "Mizoram has ~84.5% forest cover; Madhya Pradesh has highest total forest area by sq km.", "प्रतिशत के आधार पर मिजोरम तथा कुल क्षेत्रफल के आधार पर मध्य प्रदेश प्रथम है।"),
        ("Which Indian state possesses the largest total forest area in square kilometers?", "कुल क्षेत्रफल (वर्ग किमी) की दृष्टि से भारत के किस राज्य में सर्वाधिक वन क्षेत्र है?", "Madhya Pradesh", "मध्य प्रदेश (Madhya Pradesh)", ["Arunachal Pradesh", "Chhattisgarh", "Odisha"], ["अरुणाचल प्रदेश", "छत्तीसगढ़", "ओडिशा"], "Madhya Pradesh holds ~77,493 sq km of forest area per India State of Forest Report.", "भारत वन स्थिति रिपोर्ट के अनुसार सर्वाधिक वन क्षेत्रफल मध्य प्रदेश में है।"),
        ("Mangrove tidal forests in India are most extensively developed in the delta of", "भारत में मैंग्रोव (ज्वारीय) वन सर्वाधिक विस्तार से किस डेल्टा में पाए जाते हैं?", "Sundarbans Delta (West Bengal, Ganga-Brahmaputra)", "सुंदरवन डेल्टा (पश्चिम बंगाल - गंगा-ब्रह्मपुत्र)", ["Godavari Delta", "Mahanadi Delta", "Krishna Delta"], ["गोदावरी डेल्टा", "महानदी डेल्टा", "कृष्णा डेल्टा"], "Sundarbans is world's largest mangrove forest, home to Royal Bengal Tigers and Sundari trees.", "सुंदरी वृक्षों वाला सुंदरवन विश्व का सबसे बड़ा मैंग्रोव दलदली वन क्षेत्र है।"),
        ("Pneumatophores (breathing roots) are specialized adaptations found in which plants?", "न्यूमैटोफोर (श्वसन जड़ें) किन पौधों में पाई जाने वाली विशेष अनुकूलन संरचनाएं हैं?", "Mangrove plants (Halophytes like Rhizophora)", "मैंग्रोव पौधे (लवणोद्भिद जैसे राइजोफोरा)", ["Desert xerophytes", "Submerged hydrophytes", "Epiphytic orchids"], ["मरुद्भिद", "जलमग्न पौधे", "अधिपादप"], "Vertical root spikes project upward out of oxygen-deprived saline mud to absorb air.", "दलदली खारी मिट्टी में ऑक्सीजन लेने के लिए जड़ें ऊपर हवा में निकल आती हैं।"),
        ("Insectivorous plants grow typically in soils that are severely deficient in", "कीटभक्षी पौधे प्रायः किस तत्व की कमी वाली मिट्टी में उगते हैं?", "Nitrogen", "नाइट्रोजन (Nitrogen)", ["Carbon", "Phosphorus", "Potassium"], ["कार्बन", "फॉस्फोरस", "पोटैशियम"], "Peat bogs are nitrogen-starved; plants digest insects to absorb amino nitrogen.", "दलदली मृदा में नाइट्रोजन की कमी पूरी करने हेतु पौधे कीटों का शिकार करते हैं।"),
        ("The gaseous byproduct released during the anaerobic digestion of organic matter is", "अवायवीय अपघटन (Anaerobic Digestion) में उत्पन्न होने वाली प्रमुख गैस कौन सी है?", "Methane (CH4 / Biogas)", "मेथेन (CH4 / बायोगैस)", ["Oxygen", "Nitrogen dioxide", "Sulphur trioxide"], ["ऑक्सीजन", "नाइट्रोजन डाइऑक्साइड", "सल्फर ट्राइऑक्साइड"], "Methanogenic archaebacteria produce methane and CO2 from organic slurries.", "मेथेनोजेनिक बैक्टीरिया ऑक्सीजन की अनुपस्थिति में बायोगैस (मेथेन) बनाते हैं।"),
        ("The biological process of converting atmospheric nitrogen into plant-usable nitrates is called", "वायुमंडलीय नाइट्रोजन को पौधों द्वारा ग्रहण योग्य नाइट्रेट में बदलना क्या कहलाता है?", "Nitrogen Fixation", "नाइट्रोजन स्थिरीकरण (Nitrogen Fixation)", ["Nitrification", "Denitrification", "Ammonification"], ["नाइट्रीकरण", "विनाइट्रीकरण", "अमोनीकरण"], "Carried out by biological fixers (Rhizobium, Azotobacter, blue-green algae) or lightning.", "राइजोबियम और नील-हरित शैवाल हवा की नाइट्रोजन को नाइट्रेट्स में बदलते हैं।"),
        ("Excessive runoff of chemical fertilizers into lakes causing algal blooms and oxygen depletion is termed", "कृषि उर्वरकों के जलाशयों में बहने से शैवालों की अत्यधिक वृद्धि व ऑक्सीजन की कमी क्या कहलाती है?", "Eutrophication", "सुपोषण / यूट्रोफिकेशन (Eutrophication)", ["Biomagnification", "Bioaccumulation", "Salinization"], ["जैव आवर्धन", "जैव संचय", "लवणीकरण"], "Nitrate and phosphate enrichment causes explosive algal blooms, choking aquatic life.", "फॉस्फेट और नाइट्रेट के कारण शैवाल पनपते हैं और पानी की घुलित ऑक्सीजन खत्म हो जाती है।")
    ]
    pl = plant_pool[idx]
    ans_idx = (140 + idx) % 4
    qs.append(make_question(
        140, SEC_EN, SEC_HI, U_EN, U_HI,
        pl[0], pl[1], pl[2], pl[3], pl[4], pl[5],
        pl[6], pl[7],
        ans_idx
    ))

    assert len(qs) == 10, f"Expected 10 questions, got {len(qs)}"
    return qs
